/** Generated by scaffold-crud-pages. Query hooks for TopicTags.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchTopicTagsList,
  fetchTopicTagsById,
  createTopicTags,
  updateTopicTags,
  deleteTopicTags,
  type FetchTopicTagsListParams,
} from '~/services/httpServices/topicTagsService';
import type { CreateTopicTagsRequest, UpdateTopicTagsRequest } from '~/types/topic-tags';

const DOMAIN = 'topicTags';

export function useTopicTagsList(params?: FetchTopicTagsListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchTopicTagsList(params),
  });
}

export function useTopicTags(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchTopicTagsById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreateTopicTags() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateTopicTagsRequest) => createTopicTags(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdateTopicTags() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdateTopicTagsRequest }) =>
      updateTopicTags(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeleteTopicTags() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deleteTopicTags(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
